rx = re.compile(r'<tr( class="ask")?><td>(\d+)</td>((?:<td class="k[^"]*" title="[^"]*">\w+</td>)+)</tr>')
out = []
for m in rx.finditer(s):
    n = int(m.group(2)); codes = re.findall(r'>(\w+)</td>', m.group(3)); d = {c[0]: c for c in codes}
    src = 'sampled from SMCalFlow or written to match' + ('; slip known' if n in KNOWN else '; slip unseen' if n in UNSEEN else '')
    out.append({'id': n, 'today': W[d['W']], 'codes': ' '.join(codes), 'ask': 'yes' if m.group(1) else '', 'request': R[n], 'sources': src})
assert len(out) == 100 and len(R) == 100
with open(OUT, 'w', encoding='utf-8-sig', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(out[0])); w.writeheader(); w.writerows(out)
print('written', len(out))
